// @vitest-environment node
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { encode } from "@auth/core/jwt";
import { Hono } from "hono";
import { contextStorage } from "hono/context-storage";
import { auth } from "./auth";

const secret = "fictional-upgrade-test-secret-never-used-in-production";
const user = { sub: "fictional-27", email: "fixture@ju.edu", name: "Fictional Fundraiser" };
// Generated by Auth.js 0.37.4 with the fictional secret above, not live cookies.
const oldSecureToken = "eyJhbGciOiJkaXIiLCJlbmMiOiJBMjU2Q0JDLUhTNTEyIiwia2lkIjoibUpqejh1alBzZmo0dFFTaC14Q3h6OUYyUG1iWjdyaVNBc04xeldCLXZ2ZVFGM3FCRE83QWZIeFE1UjB4bDg0ck40eG5aaF9mODNCVGZrUHNjZVlYaEEifQ..s25todbViByQuv0feYHhVw.AoE00KmmtKa8XE5_XEjTdT-rGAaK1C66dvpQIUtx1_pUvcDCFYSKaz2XgrYB5QH-qEKflXNvmnWWZquCwCGlxutX1g-t92ZNBHAAgoMjd5Bb8JYMn6IV2jYMBHc0aG81WdcgPk7BOZBZaU2ghqW2MvWNmj10deHmy9wC5-12ZSykaKUR_3ObujcRDLwtBdeAUPgDxTfiCyRfXZ1DHOgr1A.4pArj79BORZM02AbG-LAZ2Upj5bsBl9Y-RZJ71vx2HY";
const oldLocalToken = "eyJhbGciOiJkaXIiLCJlbmMiOiJBMjU2Q0JDLUhTNTEyIiwia2lkIjoicnh0aktEbzF5RWh0WEJiR0UwYjBhMVZWQ1JtWEJGalh3NUFVeXR2LThDUUZzQlkweTVDVGl6S245eVFzaGtaa3dkcjRqQlc3djdhUnhIa2gya2tNbkEifQ..MUjOGJdtwBMwiGXHZSVmUw.4Qmvk5y7HEiWh7SzW1yPhaePnv3usUCxt3cWjkxY_nRLCNJfGlfWOTTZlxU9xC9P8cgInblNBLl3vn2utmPiiH_t-Z4aH3C4xZBmvI_wg_CdcUz1a-3ImnRJy_gsfWL6A4bGlVuOaF9-MucTmPm7l2XTByGGFbpfXmH4MKxF-O6jrq3LEQU4-0COTCdD5Dv9Y43vhJdaI1lXvkMcBF9uQg.-WencY7wrJ27KjpxP_mK--_inFl5PNe8j5yBCx-H_uQ";
const secureName = "__Secure-authjs.session-token";

function request(cookie, url = "https://app.example.test/", headers = {}) {
  return new Request(url, { headers: { ...(cookie ? { cookie } : {}), ...headers } });
}

describe("real Auth.js session compatibility", () => {
  beforeEach(() => {
    vi.stubEnv("AUTH_SECRET", secret);
    vi.stubEnv("WORKSPACE_EMAIL_DOMAIN", "ju.edu");
  });
  afterEach(() => vi.unstubAllEnvs());

  it("retains pre-upgrade HTTPS sessions", async () => {
    expect(await auth(request(`${secureName}=${oldSecureToken}`))).toMatchObject({
      user: { id: user.sub, email: user.email, name: user.name },
    });
  });
  it("retains pre-upgrade local development sessions", async () => {
    expect(await auth(request(`authjs.session-token=${oldLocalToken}`, "http://localhost/")))
      .toMatchObject({ user: { id: user.sub } });
  });
  it("reads chunked sessions behind the HTTPS proxy", async () => {
    const halfway = Math.floor(oldSecureToken.length / 2);
    const cookie = `${secureName}.1=${oldSecureToken.slice(halfway)}; ${secureName}.0=${oldSecureToken.slice(0, halfway)}`;
    expect(await auth(request(cookie, "http://localhost/", { "x-forwarded-proto": "https" })))
      .toMatchObject({ user: { id: user.sub } });
  });
  it("accepts newly issued sessions", async () => {
    const token = await encode({ token: user, secret, salt: secureName });
    expect(await auth(request(`${secureName}=${token}`))).toMatchObject({ user: { id: user.sub } });
  });
  it("resolves the current request through the real Hono context middleware", async () => {
    const app = new Hono();
    app.use(contextStorage());
    app.get("/", async (context) => context.json(await auth()));
    const response = await app.request(request(`${secureName}=${oldSecureToken}`));
    expect(response.status).toBe(200);
    expect(await response.json()).toMatchObject({ user: { id: user.sub } });
  });
  it.each([
    ["outside workspace", { ...user, email: "fixture@example.test" }, 3600],
    ["missing email", { sub: user.sub }, 3600],
    ["expired", user, -3600],
  ])("rejects %s sessions", async (_, tokenData, maxAge) => {
    const token = await encode({ token: tokenData, secret, salt: secureName, maxAge });
    expect(await auth(request(`${secureName}=${token}`))).toBeNull();
  });
  it.each([undefined, `${secureName}=invalid`, `${secureName}=${oldSecureToken.slice(0, -5)}abcde`])(
    "rejects absent or damaged cookies without crashing", async (cookie) => {
      expect(await auth(request(cookie))).toBeNull();
    },
  );
  it("rejects a malformed bearer escape without an unhandled exception", async () => {
    await expect(auth(request(null, undefined, { authorization: "Bearer %E0%A4%A" }))).resolves.toBeNull();
  });
  it("fails closed when the server secret is missing", async () => {
    vi.stubEnv("AUTH_SECRET", "");
    expect(await auth(request(`${secureName}=${oldSecureToken}`))).toBeNull();
  });
});
